from pathlib import Path
from urllib.request import Request, urlopen
import hashlib, base64, json, zlib

# Pinned independent test application; no network dependency for page source.
APP = ""
output = Path("independent-ielts-public")
output.mkdir(exist_ok=True)
for name, text in json.loads(zlib.decompress(base64.b64decode(APP))).items():
    (output / name).write_text(text, encoding="utf-8")
    print("Prepared", name, flush=True)
# Copy the original uploaded recording into this host during publication.
request = Request("https://ielts-practice-room.marturillas122813.chatgpt.site/audio/diagnostic-full.mp3", headers={"User-Agent":"IELTS-Static-Publisher/1.0"})
with urlopen(request, timeout=120) as response:
    audio = response.read()
if hashlib.sha256(audio).hexdigest() != "b8aca6c3ef4cdd1416ef86c3ecd5f0a377e8c8d43c09872b19dc00395c836706":
    raise RuntimeError("Audio integrity check failed")
(output / "audio").mkdir(exist_ok=True)
(output / "audio/diagnostic-full.mp3").write_bytes(audio)
print("Original audio copied:", len(audio), "bytes", flush=True)
print("Standalone student site ready.", flush=True)
